  dict(id="a3_lines", es="Lines: thick, thin, straight, curved", hu="Vonalak: vastag, vékony, egyenes, görbe", pages="Unit 3 · start", kind="Art · művészet", img="a_lines",
       es_text="A line can be thick or thin, straight or curved. An angle is a corner where two lines meet. In this unit we draw with lines and angles, with light and shade. A spiral is a line that turns round and round.",
       hu_text="A vonal lehet thick, vastag vagy thin, vékony; straight, egyenes vagy curved, görbe. Az angle a szög, a sarok, ahol két vonal találkozik. Ebben a fejezetben vonalakkal és szögekkel, fénnyel és árnyékkal rajzolunk. A spiral a spirál: olyan vonal, amely körbe-körbe csavarodik.",
       examples=[("thick, thin","vastag, vékony"),("straight, curved","egyenes, görbe"),("line, angle","vonal, szög"),("spiral","spirál")]),
  dict(id="a3_artists", es="Three famous pictures: Klimt, Lempicka, Mondrian", hu="Három híres kép: Klimt, Lempicka, Mondrian", pages="Unit 3 · 1", kind="Artists · művészek", img="a_three",
       es_text="Gustav Klimt painted The Tree of Life in 1909: lots of decorated spirals and gold colour. Tamara de Lempicka painted Madame Boucard in 1931: an elegant lady in a red dress. Piet Mondrian painted Place de la Concorde in 1943: straight, thick black lines with a few coloured squares. What does each picture show? Who were the three artists?",
       hu_text="Gustav Klimt 1909-ben festette Az élet fája, The Tree of Life, című képet: sok díszes spirál és arany szín. Tamara de Lempicka 1931-ben festette a Madame Boucard-t: egy elegáns hölgy piros ruhában. Piet Mondrian 1943-ban festette a Place de la Concorde-ot: egyenes, vastag fekete vonalak, néhány színes négyzettel. Mit ábrázol az egyes kép? Ki volt a három művész?",
       examples=[("tree of life","az élet fája"),("Klimt – spirals, gold","Klimt – spirálok, arany"),("Lempicka – a lady in red","Lempicka – hölgy pirosban"),("Mondrian – black lines, squares","Mondrian – fekete vonalak, négyzetek")],
       gallery=[("a_g_spirals","spirals and gold (like Klimt)","spirálok és arany (Klimt módjára)"),("a_g_grid","black lines and coloured squares (like Mondrian)","fekete vonalak és színes négyzetek (Mondrian módjára)")]),
  dict(id="a3_smoke", es="Smoke and fire", hu="Füst és tűz", pages="Unit 3 · 2", kind="Art · művészet", img="a_smoke",
       es_text="One task: what is hiding behind the smoke? The page has a smoky drawing made of tangled circles, and you guess what is behind it. Later in the unit you build a fire engine, so the topic is fire, smoke and firefighters.",
       hu_text="Az egyik feladat: mi bújik meg a füst mögött? A lapon egy füstös, kuszált körökből álló rajz van, és te találod ki, mi rejtőzik mögötte. A fejezet végén tűzoltóautót, fire engine, építesz, ezért a téma a tűz, a füst és a tűzoltók.",
       examples=[("fire, smoke","tűz, füst"),("fire engine","tűzoltóautó"),("firefighter","tűzoltó"),("hide, behind","elbújik, mögött")]),
  dict(id="a3_stilllife", es="Still life", hu="Csendélet", pages="Unit 3 · 3", kind="Art · művészet", img="a_stilllife",
       es_text="A still life is a picture of objects: fruit, a vase, bowls. They do not move, so life is still. Famous still-life painters are Diego Velázquez and Georgia O'Keeffe, who painted flowers and objects. Put some objects together, look at the light, draw the lines and colour it. Where is the darkest part?",
       hu_text="A csendélet, still life, olyan kép, amelyen tárgyakat látsz: gyümölcsöt, vázát, edényeket. Nem mozognak, ezért csendes az élet. Híres csendéletfestő Diego Velázquez és Georgia O'Keeffe, aki virágokat és tárgyakat festett. Rakj össze néhány tárgyat, nézd meg a fényt, rajzold meg a vonalakat, és színezd ki. Hol van a legsötétebb rész?",
       examples=[("still life","csendélet"),("fruit, vase, bowl","gyümölcs, váza, tál"),("Velázquez, O'Keeffe","Velázquez, O'Keeffe"),("the darkest part","a legsötétebb rész")]),
  dict(id="a3_comic", es="What is a comic?", hu="Mi az a képregény?", pages="Unit 3 · 4", kind="Art · művészet", img="a_comic",
       es_text="A comic is a story told with pictures, with or without words. A comic is made of boxes of different sizes and shapes. The words go in speech bubbles. Onomatopoeia are words that show sounds: CRASH, BOOM, WOW. I drew a comic. How does the character feel? He is happy, sad or angry.",
       hu_text="A képregény, comic, olyan történet, amelyet képekkel mesélnek el, szöveggel vagy anélkül. A képregény különböző méretű és formájú dobozokból áll. A szöveg szövegbuborékokban, speech bubble, van. Az onomatopoeia a hangutánzó szó: CRASH, csattanás; BOOM, bumm; WOW, hűha. I drew a comic: képregényt rajzoltam. How does the character feel? Hogy érzi magát a szereplő? He is happy, sad or angry.",
       examples=[("comic","képregény"),("speech bubble","szövegbuborék"),("onomatopoeia: crash, boom, wow","hangutánzó szó: csatt, bumm, hűha"),("How does the character feel?","Hogy érzi magát a szereplő?")]),
  dict(id="a3_script", es="The script: describing your character", hu="A forgatókönyv: a szereplőd leírása", pages="Unit 3 · 5", kind="Project · projekt", img="a_script",
       es_text="At the end of the unit you plan a film. First invent the characters and describe them with the word bank: tall or short, fat or thin, old or young; big or small eyes; blue, brown or green eyes; long or short hair; blond, brown or dark hair. My character is tall. My character has long hair and blue eyes. A storyboard is a picture plan: drawings and notes about the scenes and where the camera is. The script is the written plan of the film.",
       hu_text="A fejezet végén filmet tervezel. Először kitalálod a szereplőket, és leírod őket a szógyűjtemény szavaival: tall, magas vagy short, alacsony; fat, kövér vagy thin, vékony; old, öreg vagy young, fiatal; big eyes, nagy szemek vagy small eyes, kis szemek; blue, brown, green eyes: kék, barna, zöld szemek; long hair, hosszú haj vagy short hair, rövid haj; blond, brown, dark hair: szőke, barna, sötét haj. My character is tall: a szereplőm magas. A storyboard képes terv: rajzok és jegyzetek a jelenetekről és arról, honnan néz a kamera. A script a film írott forgatókönyve.",
       examples=[("tall, short, fat, thin","magas, alacsony, kövér, vékony"),("long hair, short hair, blond hair","hosszú haj, rövid haj, szőke haj"),("My character has blue eyes.","A szereplőmnek kék szeme van."),("script, storyboard, scene, camera","forgatókönyv, képes forgatókönyv, jelenet, kamera")]),
  dict(id="a3_challenge", es="Challenge: Achieve gender equality", hu="A nagy kihívás: egyenlőség a művészetben", pages="Unit 3 · 6", kind="Challenge · kihívás", img="a_display",
       es_text="The last team task: display works of art made by women. The goal is that everybody understands that girls and boys can be equally good artists. At the end of the book there are worksheets to cut out, like the window: cut out, glue and assemble.",
       hu_text="Az utolsó csapatfeladat: állítsatok ki, display, olyan műalkotásokat, amelyeket nők készítettek. A cél, hogy mindenki értse: a lányok és a fiúk egyformán jó művészek lehetnek. A könyv végén kivágható munkalapok vannak, például az ablak: cut out, kivág; glue, ragaszt; assemble, összeállít.",
       examples=[("display","kiállít, megmutat"),("women","nők"),("equality","egyenlőség"),("cut out, glue, assemble","kivág, ragaszt, összeállít")]),
